begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public, pg_catalog;
select plan(27);

select has_table('consulting_os','goals','Goal is first-class');
select has_table('consulting_os','value_hypotheses','Value Hypothesis is first-class');
select has_table('consulting_os','value_evaluations','Harvest and Soil evaluation is first-class');
select has_table('consulting_os','emergent_organization_profiles','New Reality is first-class');
select has_table('consulting_os','baseline_snapshots','Baseline is first-class');
select has_view('consulting_os','value_outcome_pathways','Value chain has a governed projection');
select has_view('consulting_os','client_progress','Client progress has a curated projection');
select has_function('consulting_os','create_baseline_snapshot',array['uuid','timestamp with time zone','text','text','uuid','uuid[]','text[]','text[]'],'Baseline creation is atomic');
select results_eq($$select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='consulting_os' and c.relname in ('strategic_priorities','goals','value_hypotheses','indicators','measurements','outcomes','value_evaluations','learnings','outcome_decisions','emergent_organization_profiles','emergent_profile_members','emergent_reality_differences','organizational_stories','organizational_story_links','baseline_snapshots','baseline_snapshot_members') and c.relrowsecurity$$,array[16::bigint],'Every Phase 7 table enforces RLS');
select results_eq($$select enumlabel from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='consulting_os' and t.typname='outcome_disposition' order by enumsortorder$$,array['SUSTAIN','IMPROVE','SCALE','STOP','REINVENT'],'Human outcome decisions are controlled');





select results_eq($$select count(*) from consulting_os.value_outcome_pathways where outcome_id='a7400000-0000-4000-8000-000000000012' and baseline_value='6.2 days' and target_value='3.0 days' and measurement_value='3.4 days'$$,array[1::bigint],'Goal, target, and measurement history remain traceable');
select results_eq($$select count(*) from consulting_os.entity_relationships where target_id='a7400000-0000-4000-8000-000000000012' and relationship_type='CAUSES'$$,array[0::bigint],'Outcome does not imply causation');
select results_eq($$select count(*) from consulting_os.value_evaluations where id='a7400000-0000-4000-8000-000000000013' and harvest_finding<>'' and soil_finding<>'' and mission_rating<>'NOT_ASSESSED' and human_rating<>'NOT_ASSESSED' and operational_rating<>'NOT_ASSESSED' and economic_rating<>'NOT_ASSESSED' and sustainable_rating<>'NOT_ASSESSED'$$,array[1::bigint],'Harvest, Soil, and all five value dimensions are reviewed');
select results_eq($$select count(*) from consulting_os.outcome_decisions where learning_id='a7400000-0000-4000-8000-000000000014' and disposition='SCALE'$$,array[1::bigint],'Validated Learning produces an authorized disposition');
select results_eq($$select count(*) from consulting_os.future_states where id='a7400000-0000-4000-8000-000000000005' and desired_condition='Bounded authority near work'$$,array[1::bigint],'Future State remains unchanged');
select results_eq($$select count(*) from consulting_os.emergent_reality_differences where emergent_profile_id='a7400000-0000-4000-8000-000000000017' and actual_state<>intended_state$$,array[1::bigint],'New Reality preserves its difference from intent');

select throws_ok($$insert into consulting_os.entity_relationships(organization_id,engagement_id,relationship_type,source_type,source_id,target_type,target_id,origin,review_status,rationale,created_by) values ('a7aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a7300000-0000-4000-8000-000000000001','CAUSES','REINVENTION_INITIATIVE','a7400000-0000-4000-8000-000000000003','OUTCOME','a7400000-0000-4000-8000-000000000012','AI','ACCEPTED','AI causal assertion.','a7200000-0000-4000-8000-000000000001')$$,'23514',null,'AI cannot create an accepted causal edge');
select throws_ok($$insert into consulting_os.entity_relationships(organization_id,engagement_id,relationship_type,source_type,source_id,target_type,target_id,origin,review_status,rationale,validated_by,validated_at,created_by) values ('a7aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a7300000-0000-4000-8000-000000000001','CAUSES','REINVENTION_INITIATIVE','a7400000-0000-4000-8000-000000000003','OUTCOME','a7400000-0000-4000-8000-000000000012','HUMAN','ACCEPTED','Incomplete causal assertion.','a7200000-0000-4000-8000-000000000001',now(),'a7200000-0000-4000-8000-000000000001')$$,'23514',null,'CAUSES rejects missing evidence and alternatives');
select results_eq($$select count(*) from consulting_os.entity_relationships where relationship_type='CONTRIBUTED_TO' and target_id='a7400000-0000-4000-8000-000000000012'$$,array[1::bigint],'Human-reviewed contribution is permitted');
select results_eq($$select count(*) from consulting_os.entity_relationships where relationship_type='CAUSES' and target_id='a7400000-0000-4000-8000-000000000012' and alternative_explanations<>''$$,array[1::bigint],'Exceptional human-validated CAUSES preserves its proof');
select ok(not has_table_privilege('authenticated','consulting_os.baseline_snapshots','INSERT'),'Baseline cannot be inserted directly by authenticated users');

set local role authenticated;
select set_config('request.jwt.claim.sub','a7100000-0000-4000-8000-000000000001',true);
select lives_ok($$select consulting_os.create_baseline_snapshot('a7400000-0000-4000-8000-000000000017',now(),'Next-cycle organizational reality','Approved profile becomes the next inquiry baseline.','a7300000-0000-4000-8000-000000000002',array['a7400000-0000-4000-8000-000000000008'::uuid],array['GOAL'],array['Decision latency goal'])$$,'Authorized consultant can atomically establish a baseline');
select results_eq($$select count(*) from consulting_os.current_baselines where source_profile_id='a7400000-0000-4000-8000-000000000017' and jsonb_array_length(manifest)=2$$,array[1::bigint],'Baseline manifest captures profile and selected versioned state');
select results_eq($$select count(*) from consulting_os.entity_relationships where relationship_type='BECOMES_BASELINE_FOR' and source_id='a7400000-0000-4000-8000-000000000017'$$,array[1::bigint],'Profile explicitly becomes the next baseline');
select throws_ok($$select consulting_os.create_baseline_snapshot('a7400000-0000-4000-8000-000000000017',now(),'Unsafe baseline','Attempt private promotion.',null,array['a7400000-0000-4000-8000-000000000019'::uuid],array['PRIVATE_NOTE'],array['Private note'])$$,'42501',null,'Shared baseline rejects consultant-private content');
select throws_ok($$update consulting_os.baseline_snapshots set scope='Rewrite' where source_profile_id='a7400000-0000-4000-8000-000000000017'$$,'55000',null,'Baseline is immutable');

reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a7100000-0000-4000-8000-000000000002',true);
select results_eq($$select count(*) from consulting_os.client_progress where organization_id='a7aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$,array[0::bigint],'Other tenant cannot read client progress');
reset role;

select * from finish();
rollback;
